def fetch_with_backoff(url, attempts=5):
    for attempt in range(attempts):
        try:
            return session.get(url, timeout=10)
        except RequestException:
            time.sleep(2 ** attempt)
    raise RuntimeError('gave up after retries')

export function useDebouncedValue<T>(value: T, delayMs = 200) {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => { const id = setTimeout(() => setDebounced(value), delayMs); return () => clearTimeout(id); }, [value, delayMs]);
  return debounced;
}

/// Cooperative cancellation flag shared between a requester and workers.
pub struct CancellationToken(Arc<AtomicBool>);
impl CancellationToken { pub fn cancel(&self) { self.0.store(true, Ordering::Release); } }

